#include <iostream>
#include <vector>

int estimar(int piezas) {
    if (piezas < 0 || piezas > 10) {
        return -1;
    }

    if (piezas == 0) {
        return 0;
    }

    return 3 + 2 * piezas;
}

int main() {
    std::vector<int> pedidos{0, 2, 11, -1, 5};
    int total{0};

    for (int piezas : pedidos) {
        int minutos{estimar(piezas)};

        std::cout << "Piezas=" << piezas << ":";

        if (minutos == -1) {
            std::cout << "Invalido\n";
        } else {
            total += minutos;
            std::cout << minutos << "\n";
        }
    }

    std::cout << "Total=" << total;

    return 0;
}

